-- ==============================================================================
-- SOR CONNECT: JOB POSTINGS & HIRING POSITIONS TABLE
-- Execute this script in your Supabase SQL Editor:
-- https://supabase.com/dashboard/project/znjpzipedsowuyrpotgb/sql
-- ==============================================================================

CREATE TABLE IF NOT EXISTS public.job_postings (
    id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    title TEXT NOT NULL,
    department TEXT NOT NULL DEFAULT 'Engineering & Design',
    location TEXT NOT NULL DEFAULT 'Pan-India',
    experience TEXT NOT NULL DEFAULT '2+ Years',
    type TEXT NOT NULL DEFAULT 'Full-time',
    description TEXT,
    requirements JSONB DEFAULT '[]'::jsonb,
    active BOOLEAN NOT NULL DEFAULT TRUE,
    order_index INT DEFAULT 0,
    created_at TIMESTAMPTZ DEFAULT NOW(),
    updated_at TIMESTAMPTZ DEFAULT NOW()
);

-- Also ensure public.careers has resume_url and resume_name
ALTER TABLE IF EXISTS public.careers ADD COLUMN IF NOT EXISTS resume_url TEXT;
ALTER TABLE IF EXISTS public.careers ADD COLUMN IF NOT EXISTS resume_name TEXT;
ALTER TABLE IF EXISTS public.careers ADD COLUMN IF NOT EXISTS availability TEXT;
ALTER TABLE IF EXISTS public.careers ADD COLUMN IF NOT EXISTS portfolio TEXT;
ALTER TABLE IF EXISTS public.careers ADD COLUMN IF NOT EXISTS cover_note TEXT;

-- Enable Row Level Security (RLS)
ALTER TABLE public.job_postings ENABLE ROW LEVEL SECURITY;

-- Policies for public reading and admin full access
DROP POLICY IF EXISTS "Public can view active job postings" ON public.job_postings;
CREATE POLICY "Public can view active job postings"
ON public.job_postings
FOR SELECT
USING (true);

DROP POLICY IF EXISTS "Admin full access on job postings" ON public.job_postings;
CREATE POLICY "Admin full access on job postings"
ON public.job_postings
FOR ALL
USING (true)
WITH CHECK (true);

-- Performance Indexes
CREATE INDEX IF NOT EXISTS idx_job_postings_active ON public.job_postings (active);
CREATE INDEX IF NOT EXISTS idx_job_postings_order ON public.job_postings (order_index ASC);

